sources.shader_maze_hlsl5_fragment:
static float4 pixel;
static float3 color;

struct SPIRV_Cross_Input
{
    float3 color : TEXCOORD0;
};

struct SPIRV_Cross_Output
{
    float4 pixel : SV_Target0;
};

void frag_main()
{
    pixel = float4(color, 1.0f);
}

SPIRV_Cross_Output main(SPIRV_Cross_Input stage_input)
{
    color = stage_input.color;
    frag_main();
    SPIRV_Cross_Output stage_output;
    stage_output.pixel = pixel;
    return stage_output;
}

sources.shader_maze_hlsl5_vertex:
static float4 gl_Position;
static float3 color;
static float3 rgb;
static float2 position;

struct SPIRV_Cross_Input
{
    float2 position : TEXCOORD0;
    float3 rgb : TEXCOORD1;
};

struct SPIRV_Cross_Output
{
    float3 color : TEXCOORD0;
    float4 gl_Position : SV_Position;
};

void vert_main()
{
    color = rgb;
    gl_Position = float4(position, 0.0f, 1.0f);
}

SPIRV_Cross_Output main(SPIRV_Cross_Input stage_input)
{
    rgb = stage_input.rgb;
    position = stage_input.position;
    vert_main();
    SPIRV_Cross_Output stage_output;
    stage_output.gl_Position = gl_Position;
    stage_output.color = color;
    return stage_output;
}

sources.shader_maze_metal_ios_fragment:
#include <metal_stdlib>
#include <simd/simd.h>

using namespace metal;

struct main0_out
{
    float4 pixel [[color(0)]];
};

struct main0_in
{
    float3 color [[user(locn0)]];
};

fragment main0_out main0(main0_in in [[stage_in]])
{
    main0_out out = {};
    out.pixel = float4(in.color, 1.0);
    return out;
}

